BEGIN;CREATE TABLE IF NOT EXISTS support_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,reporter_identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE RESTRICT,assignment_id uuid REFERENCES work_assignments(id) ON DELETE SET NULL,category text NOT NULL CHECK(category IN('schedule','payment','work_conditions','cancellation','dispute','other')),description text NOT NULL CHECK(char_length(description) BETWEEN 1 AND 4000),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN('normal','high','urgent')),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','reviewing','resolved','dismissed')),resolution_note text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);ALTER TABLE support_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE support_cases FORCE ROW LEVEL SECURITY;CREATE POLICY support_cases_tenant ON support_cases USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE ON support_cases TO app_runtime;COMMIT;